delete from symptom_infos
where symptom_id in (
  select id from symptoms where slug in (
    'colic', 'teething', 'newborn_heat_rash', 'stool_color_abnormal', 'burping_trouble', 'spit_up_reflux', 'runny_stuffy_nose', 'fever', 'rash', 'sleep_regression', 'constipation', 'diarrhea', 'hiccups', 'prickly_heat', 'jaundice', 'eye_discharge_tearing', 'thrush', 'umbilical_cord', 'newborn_marks', 'newborn_hormonal', 'dimple', 'tongue_tie', 'vaccination', 'formula_prep', 'breastmilk_storage', 'lochia', 'baby_blues', 'engorgement', 'nipple_care', 'breastfeeding_start', 'milk_supply', 'postpartum_recovery'
  )
);

insert into symptom_infos (symptom_id, summary, sections, emergency, sources)
